// Area-weighted centre of a shape's largest polygon (where its label goes).
function ringCentre(ring) {
  let a = 0, cx = 0, cy = 0;
  for (let k = 0; k + 1 < ring.length; k++) {
    const [x0, y0] = ring[k], [x1, y1] = ring[k + 1];
    const f = x0 * y1 - x1 * y0;
    a += f;
    cx += (x0 + x1) * f;
    cy += (y0 + y1) * f;
  }
  return a ? { area: Math.abs(a / 2), x: cx / (3 * a), y: cy / (3 * a) } : { area: 0, x: ring[0][0], y: ring[0][1] };
}
function geometryCentre(geom) {
  let best = null;
  for (const poly of geom.coordinates) {
    const c = ringCentre(poly[0]);
    if (!best || c.area > best.area) best = c;
  }
  return best;
}
// ---- County geometry ----
// County outlines from us-atlas counties-albers-10m (public domain, built from US Census cartographic boundary files):
// https://cdn.jsdelivr.net/npm/us-atlas@3/counties-albers-10m.json, already projected to the same Albers USA screen
// frame as the state outlines (draw with an identity projection). Inlined rather than fetched from the CDN at view
// time: the dashboard frame has no network and VegaChart strips data URLs. To keep the file small the arcs were
// re-quantized to a 1/8 px grid, delta-encoded and written as base64 VLQ strings (source-map style); polygons hold
// rings of arc numbers (negative = reversed, ~i). countyFeatures() rebuilds GeoJSON for just the counties in view.
const VLQ_DIGITS = Object.fromEntries("ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/".split("").map((c, i) => [c, i]));
function unvlq(s) {
  const out = [];
  let v = 0, shift = 0;
  for (let k = 0; k < s.length; k++) {
    const d = VLQ_DIGITS[s[k]];
    v += (d & 31) * Math.pow(2, shift);
    if (d & 32) shift += 5;
    else {
      out.push(v % 2 ? -(v - 1) / 2 : v / 2);
      v = 0;
      shift = 0;
    }
  }
  return out;
}
let COUNTY_ARCS = null;
function arcPoints(i) {
  if (!COUNTY_ARCS) COUNTY_ARCS = COUNTY_TOPO.arcs.split(";").map((s) => ({ s, pts: null }));
  const a = COUNTY_ARCS[i];
  if (!a.pts) {
    const d = unvlq(a.s), q = COUNTY_TOPO.q, pts = [];
    let x = 0, y = 0;
    for (let k = 0; k + 1 < d.length; k += 2) {
      x += d[k];
      y += d[k + 1];
      pts.push([x / q, y / q]);
    }
    a.pts = pts;
  }
  return a.pts;
}
function countyGeometry(fips) {
  const g = COUNTY_TOPO.geoms[fips];
  if (!g) return null;
  let prev = 0;
  const coordinates = g.split("|").map((poly) => poly.split(",").map((r) => {
    const ring = [];
    for (const d of unvlq(r)) {
      prev += d;
      const pts = prev >= 0 ? arcPoints(prev) : arcPoints(~prev).slice().reverse();
      for (let k = ring.length ? 1 : 0; k < pts.length; k++) ring.push(pts[k]);
    }
    return ring;
  }));
  return { type: "MultiPolygon", coordinates };
}
// rows: one per county with a 5-digit `county_fips`; every row field is copied into the feature's properties.
function countyFeatures(rows) {
  const out = [];
  for (const r of rows) {
    const geometry = countyGeometry(r.county_fips);
    if (geometry) out.push({ type: "Feature", id: r.county_fips, properties: { ...r }, geometry });
  }
  return out;
}
function featureBounds(features) {
  let x0 = Infinity, y0 = Infinity, x1 = -Infinity, y1 = -Infinity;
  for (const f of features) for (const poly of f.geometry.coordinates) for (const [x, y] of poly[0]) {
    if (x < x0) x0 = x;
    if (y < y0) y0 = y;
    if (x > x1) x1 = x;
    if (y > y1) y1 = y;
  }
  return x1 > x0 ? { w: x1 - x0, h: y1 - y0 } : { w: 1, h: 0.6 };
}

// A county choropleth. `rows` carry county_fips plus fields; `field` is coloured with `scale`; rows where `muteIf(row)`
// is true are drawn in the empty colour. `marks` = [{ county_fips, text }] are labelled at the county's centre and
// ringed; `outline` = a Set of FIPS drawn with a heavy border.
function CountyMap({ t, rows, field, scale, legendTitle, legendFormat, tooltip, marks, outline, muteIf, maxHeightRatio }) {
  const [ref, width] = useWidth();
  const features = React.useMemo(() => {
    const drawn = countyFeatures(rows).map((f) => {
      const v = num(f.properties[field]);
      const muted = muteIf ? muteIf(f.properties) : false;
      return { ...f, properties: { ...f.properties, value: muted || v == null || isNaN(v) ? null : v, muted, hot: outline ? outline.has(f.id) : false } };
    });
    // When the view is one state, also draw its counties that have no row (no library data there),
    // as outlines, so the state's shape stays whole.
    const prefixes = new Set(rows.map((r) => String(r.county_fips || "").slice(0, 2)).filter(Boolean));
    if (prefixes.size !== 1) return drawn;
    const st = [...prefixes][0], have = new Set(drawn.map((f) => f.id));
    const rest = Object.keys(COUNTY_TOPO.geoms).filter((id) => id.slice(0, 2) === st && !have.has(id)).map((id) => ({
      type: "Feature", id, geometry: countyGeometry(id), properties: { county_name: "No library data", value: null, nodata: true },
    }));
    return drawn.concat(rest);
  }, [rows, field, muteIf, outline]);
  const nodata = features.some((f) => f.properties.nodata);
  const labels = React.useMemo(() => {
    const byId = Object.fromEntries(features.map((f) => [f.id, f]));
    return (marks || []).filter((m) => byId[m.county_fips]).map((m) => {
      const c = geometryCentre(byId[m.county_fips].geometry);
      return { x: c.x, y: c.y, text: m.text, kind: m.kind || "badge" };
    });
  }, [features, marks]);
  const spec = React.useMemo(() => {
    if (!width || !features.length) return null;
    const b = featureBounds(features);
    const w = Math.max(240, width);
    // The legend sits inside the chart's height (autosize fit), so add room for it below the shapes.
    const h = Math.round(Math.min(w * (maxHeightRatio || 0.75), Math.max(w * 0.32, (w * b.h) / b.w))) + 58;
    const pos = { longitude: { field: "x", type: "quantitative" }, latitude: { field: "y", type: "quantitative" } };
    const badges = labels.filter((l) => l.kind === "badge");
    const names = labels.filter((l) => l.kind === "name");
    return {
      config: vegaConfig(t),
      width: w,
      height: h,
      projection: { type: "identity" },
      layer: [
        {
          transform: [{ filter: "!datum.properties.nodata" }],
          // invalid: null keeps null-valued shapes (drawn in the empty colour) instead of dropping them.
          mark: { type: "geoshape", stroke: t.bg, strokeWidth: features.length > 400 ? 0.2 : 0.6, invalid: null },
          encoding: {
            color: {
              condition: { test: "datum.properties.value == null", value: t.pal.empty },
              field: "properties.value",
              type: "quantitative",
              scale,
              legend: {
                title: legendTitle, format: legendFormat, orient: "bottom", direction: "horizontal",
                gradientLength: Math.min(300, w - 60), gradientThickness: 12, titleOrient: "top", labelOverlap: true, titleLimit: 400,
              },
            },
            tooltip,
          },
        },
        {
          transform: [{ filter: "datum.properties.nodata" }],
          mark: { type: "geoshape", fill: t.bg, stroke: t.border, strokeWidth: 0.8 },
          encoding: { tooltip: [{ field: "properties.county_name", type: "nominal", title: "County" }] },
        },
        {
          transform: [{ filter: "datum.properties.hot" }],
          mark: { type: "geoshape", fillOpacity: 0, stroke: t.pal.ring, strokeWidth: 2 },
        },
        // Badges: a number in a ring at the county's centre. Names: halo text just above the centre.
        ...(badges.length ? [
          { data: { values: badges }, mark: { type: "circle", size: w < 500 ? 190 : 300, fill: t.bg, opacity: 0.92, stroke: t.pal.ring, strokeWidth: 1.5 }, encoding: pos },
          { data: { values: badges }, mark: { type: "text", fontSize: w < 500 ? 10 : 12, fontWeight: 700, color: t.fg }, encoding: { ...pos, text: { field: "text" } } },
        ] : []),
        ...(names.length ? [
          { data: { values: names }, mark: { type: "text", fontSize: 13, fontWeight: 700, baseline: "bottom", dy: -4, stroke: t.bg, strokeWidth: 4, strokeJoin: "round", color: t.bg }, encoding: { ...pos, text: { field: "text" } } },
          { data: { values: names }, mark: { type: "text", fontSize: 13, fontWeight: 700, baseline: "bottom", dy: -4, color: t.fg }, encoding: { ...pos, text: { field: "text" } } },
          { data: { values: names }, mark: { type: "circle", size: 22, color: t.fg, opacity: 1 }, encoding: pos },
        ] : []),
      ],
    };
  }, [t, width, features, labels, scale, legendTitle, legendFormat, tooltip, maxHeightRatio]);
  return (
    <div ref={ref} className="od-vega">
      {spec && <VegaChart spec={spec} data={features} />}
      {nodata && <div className="od-legend"><span><i style={{ background: t.bg, border: `1px solid ${t.border}` }} />No library data for the county</span></div>}
    </div>
  );
}

// A two-series trend: the picked area (accent, solid) against a comparison (grey, dashed). `rows` are long-form
// { fiscal_year, series, value }.
function trendSpec(t, narrow, { title, format, domain, series, years }) {
  const xs = { domain: years || ["2018", "2019", "2020", "2021", "2022", "2023", "2024"] };
  return {
    config: vegaConfig(t),
    height: narrow ? 200 : 230,
    layer: [
      {
        data: { values: [{ a: "2020", b: "2021" }] },
        mark: { type: "rect", color: t.muted, opacity: t.dark ? 0.12 : 0.08 },
        encoding: { x: { field: "a", type: "ordinal", scale: xs }, x2: { field: "b" } },
      },
      {
        encoding: {
          x: { field: "fy", type: "ordinal", scale: xs, axis: { title: null, labelAngle: 0, labelExpr: "'FY' + slice(datum.label, 2)" } },
          y: { field: "value", type: "quantitative", axis: { title, format, tickCount: 5 }, scale: { zero: true, ...(domain ? { domain } : {}) } },
          color: { field: "series", type: "nominal", scale: { domain: series, range: [t.pal.up, t.pal.quietLine] }, legend: series.length > 1 ? { orient: "top", title: null } : null },
          strokeDash: { field: "series", type: "nominal", scale: { domain: series, range: [[1, 0], [5, 4]] }, legend: null },
        },
        layer: [
          { mark: { type: "line", strokeWidth: 2.5, interpolate: "monotone" } },
          {
            mark: { type: "point", filled: true, size: 40, stroke: t.bg, strokeWidth: 1 },
            encoding: {
              tooltip: [
                { field: "series", title: "Where" },
                { field: "fy", title: "Fiscal year" },
                { field: "value", type: "quantitative", title, format },
              ],
            },
          },
        ],
      },
    ],
  };
}

// ---- Library growth gap: county population growth against library use and spend per resident ----

const FAST = 0.08; // the model's "Fast (8%+)" growth band (county_spend_gap growth_band), about 3x the US rate
const shortCounty = (s) => (s ? String(s).replace(/ (County|Parish|Borough|Census Area|Municipality|city)$/i, "") : "");

// Growth (x) against spend per resident (y), one dot per county sized by residents. Fast-growing counties below the
// state median are orange; the state median and the 8% line are dashed.
function growthSpendSpec(t, narrow, median, labels) {
  const x = { field: "growth", type: "quantitative", axis: { title: "Population growth, 2020 to 2024", format: "+.0%", tickCount: narrow ? 5 : 8 }, scale: { nice: true } };
  const y = { field: "spend", type: "quantitative", axis: { title: "Library spend per resident, FY2024", format: "$,.0f", tickCount: 6 }, scale: { zero: true } };
  return {
    config: vegaConfig(t),
    height: narrow ? 320 : 400,
    layer: [
      ...(median != null ? [
        { data: { values: [{ v: median }] }, mark: { type: "rule", color: t.muted, strokeDash: [4, 3] }, encoding: { y: { field: "v", type: "quantitative" } } },
        {
          data: { values: [{ v: median, text: `State median ${dollars(median)}` }] },
          mark: { type: "text", align: "right", baseline: "bottom", dy: -3, fontSize: 12, fontWeight: 600, color: t.muted, x: "width" },
          encoding: { y: { field: "v", type: "quantitative" }, text: { field: "text" } },
        },
      ] : []),
      { data: { values: [{ v: FAST }] }, mark: { type: "rule", color: t.muted, strokeDash: [4, 3] }, encoding: { x: { field: "v", type: "quantitative" } } },
      {
        data: { values: [{ v: FAST, text: "Fast growth (8%+) →" }] },
        mark: { type: "text", align: "left", baseline: "top", dx: 4, fontSize: 12, fontWeight: 600, color: t.muted, y: 2 },
        encoding: { x: { field: "v", type: "quantitative" }, text: { field: "text" } },
      },
      {
        mark: { type: "circle", opacity: 0.8, stroke: t.bg, strokeWidth: 0.6 },
        encoding: {
          x, y,
          size: { field: "residents", type: "quantitative", scale: { type: "sqrt", range: narrow ? [10, 320] : [16, 640] }, legend: null },
          color: {
            field: "group", type: "nominal",
            scale: { domain: ["Fast-growing, spends below the state median", "Other counties"], range: [t.pal.alt, t.pal.quiet] },
            legend: { orient: "top", title: null, columns: narrow ? 1 : 2, symbolOpacity: 1, labelLimit: 320 },
          },
          order: { field: "groupOrder", type: "quantitative" },
          tooltip: [
            { field: "county", title: "County" },
            { field: "growth", type: "quantitative", title: "Growth 2020 to 2024", format: "+.1%" },
            { field: "residents", type: "quantitative", title: "Residents 2024", format: "," },
            { field: "spend", type: "quantitative", title: "Spend per resident", format: "$,.2f" },
            { field: "visits", type: "quantitative", title: "Visits per resident", format: ".2f" },
          ],
        },
      },
      // Names beside the dots; near the right edge they go on the left so they are not clipped.
      ...[false, true].map((right) => ({
        data: { values: labels.filter((l) => !!l.right === right) },
        mark: { type: "text", align: right ? "right" : "left", dx: right ? -9 : 9, baseline: "middle", fontSize: 12, fontWeight: 700, color: t.fg },
        encoding: { x: { field: "growth", type: "quantitative" }, y: { field: "spend", type: "quantitative" }, text: { field: "short" } },
      })),
    ],
  };
}

