export default function Dashboard({ dashboard, givens }) {
  const t = useT();
  const narrow = useNarrow();
  const q = useQuery({ query: "nc_growth_gap", givens });
  const aboutQ = useQuery({ query: "growth_gap_about", givens });
  const cq = useQuery({ query: "nc_growth_gap_counties", givens });
  const mq = useQuery({ query: "nc_growth_gap_median", givens });
  const error = [q, cq, mq].map((x) => x.error).find(Boolean);
  const k = q.rows[0] || {};
  const picked = onlyState(cq.rows);
  const where = picked ? stateName(picked) : "US";
  const median = picked && mq.rows.length === 1 ? num(mq.rows[0].median_spend_per_resident) : null;

  const counties = React.useMemo(() => cq.rows.map((r) => {
    const growth = num(r.population_growth_2020_2024), spend = num(r.spend_per_resident_fy2024);
    const flagged = median != null && growth >= FAST && spend != null && spend < median;
    return {
      ...r, growth, spend, residents: num(r.residents_2024), visits: num(r.visits_per_resident_fy2024),
      county: r.county_name, short: shortCounty(r.county_name),
      group: flagged ? "Fast-growing, spends below the state median" : "Other counties", groupOrder: flagged ? 1 : 0,
    };
  }), [cq.rows, median]);
  const flagged = counties.filter((c) => c.groupOrder === 1).sort((a, b) => a.spend - b.spend);
  const callout = flagged[0];
  const maxGrowth = Math.max(...counties.map((c) => c.growth || 0), 0.01);
  const scatterLabels = React.useMemo(
    () => flagged.slice(0, narrow ? 2 : 4).map((c) => ({ ...c, right: c.growth > maxGrowth * (narrow ? 0.6 : 0.8) })),
    [flagged, narrow, maxGrowth]
  );

  const growth = num(k.population_growth_2020_2024);
  const change = num(k.visits_per_resident_change);
  const headline = picked ? `${dashboard.title} — ${where}` : dashboard.title;

  const growthScale = React.useMemo(() => ({ type: "linear", domain: [-0.1, 0, 0.2], range: [t.pal.divDown, t.pal.divMid, t.pal.divUp], clamp: true, interpolate: "lab" }), [t]);
  const spendScale = React.useMemo(() => ({ type: "linear", range: t.pal.seq, zero: true, interpolate: "lab", domainMax: 60, clamp: true }), [t]);
  const tooltip = React.useMemo(() => [
    { field: "properties.county_name", type: "nominal", title: "County" },
    { field: "properties.population_growth_2020_2024", type: "quantitative", title: "Growth 2020 to 2024", format: "+.1%" },
    { field: "properties.residents_2024", type: "quantitative", title: "Residents 2024", format: "," },
    { field: "properties.spend_per_resident_fy2024", type: "quantitative", title: "Library spend per resident", format: "$,.2f" },
    { field: "properties.visits_per_resident_fy2024", type: "quantitative", title: "Visits per resident", format: ".2f" },
  ], []);
  const marks = React.useMemo(() => (callout && picked ? [{ county_fips: callout.county_fips, text: callout.short, kind: "name" }] : []), [callout, picked]);
  const outline = React.useMemo(() => new Set(flagged.map((c) => c.county_fips)), [flagged]);
  const scatter = React.useMemo(() => growthSpendSpec(t, narrow, median, scatterLabels), [t, narrow, median, scatterLabels]);

  const years = (k.by_year || []).map((r) => ({ ...r, fy: String(r.fiscal_year) }));
  const series = [where];
  const vRows = years.map((r) => ({ fy: r.fy, series: where, value: num(r.visits_per_resident) }));
  const sRows = years.map((r) => ({ fy: r.fy, series: where, value: num(r.spend_per_resident) }));
  const vSpec = React.useMemo(() => trendSpec(t, narrow, { title: "Visits per resident", format: ".1f", series }), [t, narrow, where]);
  const sSpec = React.useMemo(() => trendSpec(t, narrow, { title: "Spend per resident", format: "$,.0f", series }), [t, narrow, where]);

  const ranked = (k.growth_gap || []);
  const regional = (k.regional_systems || []);

  return (
    <div className="od">
      <style>{CSS + CSS2 + CSS_ABOUT}</style>
      <h1>{headline}</h1>
      <HeadCaveat items={["Association, not cause", "Visits fell about a third US-wide too", "Regional systems split by population", "Durham FY2019 visits over-counted (NC)"]} />
      <Controls />
      {error && <div className="err">{String(error)}</div>}
      <div className={q.loading ? "loading" : ""}>
        <div className="od-kpis">
          <div className="od-kpi">
            <div className="v">{pct1(growth)}</div>
            <div className="l">Population growth, 2020 to 2024</div>
            <div className="s">US +2.5% (Census estimates, 1 July)</div>
          </div>
          <div className="od-kpi">
            <div className="v">{dec1(k.visits_per_resident_fy2024)}</div>
            <div className="l">Library visits per resident, FY2024</div>
            <div className="s">{dec1(k.visits_per_resident_fy2019)} in FY2019</div>
          </div>
          <div className="od-kpi hot">
            <div className="v">{pct(change)}</div>
            <div className="l">Visits per resident vs FY2019</div>
            <div className="s">FY2024 vs FY2019</div>
          </div>
          <div className="od-kpi">
            <div className="v">{dollars(k.spend_per_resident_fy2024)}</div>
            <div className="l">Library spend per resident, FY2024</div>
            <div className="s">{median != null ? `Median county ${dollars(median)}` : "Operating spend, as reported"}</div>
          </div>
        </div>

        <Card
          title="Population growth and library spend by county"
          sub={`Top: population growth 2020 to 2024 (blue growing, red shrinking). Bottom: library operating spend per resident, FY2024 (darker is more). Outlined: fast-growing counties (8%+) that spend below the state median${callout ? `; ${callout.short} named` : ""}.`}
        >
          <div className="od-maps stack">
            <div>
              <p className="pt">Population growth, 2020 to 2024</p>
              <CountyMap t={t} rows={cq.rows} field="population_growth_2020_2024" scale={growthScale} legendTitle="Growth (−10% to +20%+)" legendFormat="+.0%" tooltip={tooltip} marks={marks} outline={outline} />
            </div>
            <div>
              <p className="pt">Library spend per resident, FY2024</p>
              <CountyMap t={t} rows={cq.rows} field="spend_per_resident_fy2024" scale={spendScale} legendTitle="Spend per resident ($60+ darkest)" legendFormat="$,.0f" tooltip={tooltip} marks={marks} outline={outline} />
            </div>
          </div>
        </Card>

        <Card
          title="Population growth vs library spend per resident"
          sub={`One dot per county, sized by residents. Orange: fast-growing (8%+) and spending below the median ${where} county.`}
        >
          <div className="od-vega"><VegaChart spec={scatter} data={counties} /></div>
        </Card>

        <div className="od-grid">
          <Card
            title="Visits per resident, FY2018 to FY2024"
            sub={`${where}, all systems, FY2018 to FY2024. Shaded: the pandemic closures.`}
          >
            <div className="od-vega"><VegaChart spec={vSpec} data={vRows} /></div>
          </Card>
          <Card
            title="Spend per resident, FY2018 to FY2024"
            sub="Operating spend per county resident, US dollars as reported (not adjusted for inflation)."
          >
            <div className="od-vega"><VegaChart spec={sSpec} data={sRows} /></div>
          </Card>
        </div>

        <Card
          title={`The ${ranked.length} fastest-growing counties${picked ? ` in ${where}` : ""}`}
          sub={`Ranked by population growth 2020 to 2024.${median != null ? ` Spend in red is below the median county (${dollars(median)}).` : ""}`}
        >
          <div className="od-tablewrap">
            <table>
              <thead>
                <tr>
                  <th className="rank">#</th>
                  <th className="agency">County</th>
                  <th>Growth</th>
                  <th className="hide-sm">Residents 2024</th>
                  <th className="hide-sm">Visits / resident</th>
                  <th className="hide-sm">vs FY2019</th>
                  <th>Spend / resident</th>
                </tr>
              </thead>
              <tbody>
                {ranked.map((r, i) => {
                  const below = median != null && num(r.spend_per_resident_fy2024) < median;
                  return (
                    <tr key={r.county_name + i} className={callout && r.county_name === callout.county ? "callout" : ""}>
                      <td className="rank">{i + 1}</td>
                      <td className="agency">{r.county_name}</td>
                      <td className="up">{pct(num(r.population_growth_2020_2024))}</td>
                      <td className="hide-sm">{count(r.residents_2024)}</td>
                      <td className="hide-sm">{dec1(r.visits_per_resident_fy2024)}</td>
                      <td className="hide-sm">{pct(num(r.visits_per_resident_change))}</td>
                      <td className={below ? "neg" : ""}>{dollars(r.spend_per_resident_fy2024)}</td>
                    </tr>
                  );
                })}
              </tbody>
            </table>
          </div>
          {regional.length > 0 && (
            <details>
              <summary>How regional library systems are shared across counties ({count(new Set(regional.map((r) => r.system_name)).size)} systems)</summary>
              <div className="od-tablewrap">
                <table>
                  <thead>
                    <tr><th className="agency">System</th><th className="agency">County</th><th className="hide-sm">Buildings</th><th>Share of system</th></tr>
                  </thead>
                  <tbody>
                    {regional.map((r, i) => (
                      <tr key={i}>
                        <td className="agency">{titleCase(r.system_name)}</td>
                        <td className="agency">{r.county_name}</td>
                        <td className="hide-sm">{count(r.buildings)}</td>
                        <td>{share(num(r.share_of_system))}</td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </details>
          )}
        </Card>
      </div>
      <AboutData about={ABOUT} live={aboutQ.rows[0]} />
      <p className="foot">
        Sources: IMLS Public Libraries Survey FY2018 to FY2024 (public domain) and US Census county population
        estimates (Vintage 2025). Every library system with a building in a county counts toward it; a regional system
        serving several counties is shared out by population. Spend is operating spend as reported, not adjusted for
        inflation. The state median is the middle county on FY2024 spend per resident. County outlines from us-atlas
        (US Census Bureau cartographic boundaries).
      </p>
    </div>
  );
}


